import torch

# Let's check the FC weight matrix more systematically
# Find all weights > 0.7 (unusually high)
fc_w = W['fc.weight']
print("=== FC weights > 0.7 ===")
for c in range(10):
    for n in range(64):
        w = fc_w[c, n].item()
        if w > 0.7:
            print(f"  Class {c} ({CLASSES[c]}), Neuron {n}: {w:.4f}")

# Also check large negative weights (inhibitory)
print("\n=== FC weights < -0.7 ===")
for c in range(10):
    for n in range(64):
        w = fc_w[c, n].item()
        if w < -0.7:
            print(f"  Class {c} ({CLASSES[c]}), Neuron {n}: {w:.4f}")

# Let's see the full distribution of FC weights
print("\n=== FC weight percentiles ===")
all_weights = fc_w.flatten()
for p in [50, 75, 90, 95, 99, 99.5, 99.9]:
    print(f"  {p}th percentile: {all_weights.kthvalue(int(len(all_weights) * p / 100)).values.item():.4f}")

# Check if there are any neurons that are "backdoor detectors" - high weight for one class, low for others
print("\n=== Neuron selectivity (max weight / sum of abs weights) ===")
for n in range(64):
    w = fc_w[:, n]
    max_val = w.abs().max().item()
    sum_abs = w.abs().sum().item()
    if sum_abs > 0:
        selectivity = max_val / sum_abs
        if selectivity > 0.35:
            max_class = w.argmax().item()
            print(f"  Neuron {n}: selectivity={selectivity:.3f}, top_class={max_class} ({CLASSES[max_class]}), weight={w[max_class].item():.4f}")
